<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,computed,watch} from 'vue'
import axios from 'axios'
const tab=ref('creatives'),busy=ref(false),error=ref(''),notice=ref(''),creatives=ref<any[]>([]),rules=ref<any[]>([]),genres=ref<any[]>([])
const catalogGenre=ref<number|null>(null)
const title=ref(''),file=ref<File|null>(null),preview=ref(''),kind=ref('movie'),q=ref(''),offset=ref(0),total=ref(0),videos=ref<any[]>([]),selected=ref<any>(null),cues=ref<any[]>([]),revision=ref(0),source=ref(''),mainUrl=ref(''),main=ref<HTMLVideoElement|null>(null),position=ref(0),duration=ref(0),timeInput=ref('00:00:00'),cueKind=ref('mid'),creativeId=ref('')
const uuid=()=>crypto.randomUUID?.()||'10000000-1000-4000-8000-100000000000'.replace(/[018]/g,c=>(Number(c)^crypto.getRandomValues(new Uint8Array(1))[0]&15>>Number(c)/4).toString(16))
import {nodeMediaUrl,placementBody} from '../utils/adPlacement'
const headers=()=>({Authorization:'Bearer '+(localStorage.getItem('admin_token')||'cookie-session')})
const base='/api/v1/admin/ads'
let previewSession='',previewBeat:ReturnType<typeof setInterval>|null=null
async function stopPreview(){if(previewBeat)clearInterval(previewBeat);previewBeat=null;const id=previewSession;previewSession='';main.value?.pause();mainUrl.value='';if(id)try{await axios.post('/api/v1/playback/stop',{session_id:id},{headers:headers(),timeout:5000})}catch{/* Lease expires if the connection was lost. */}}
onBeforeUnmount(()=>{void stopPreview()})
async function action(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e:any){error.value=typeof e.response?.data?.detail==='string'?e.response.data.detail:e instanceof Error&&!axios.isAxiosError(e)?e.message:'Не удалось выполнить операцию. Проверьте настройки и повторите.'}finally{busy.value=false}}
async function load(){creatives.value=(await axios.get(base+'/creatives',{headers:headers()})).data;rules.value=(await axios.get(base+'/rules',{headers:headers()})).data;placements.value=(await axios.get(base+'/placements',{headers:headers()})).data}
function selectFile(e:Event){file.value=(e.target as HTMLInputElement).files?.[0]||null;if(file.value&&!title.value)title.value=file.value.name.replace(/\.[^.]+$/,'').slice(0,160)}
function upload(){void action(async()=>{if(!file.value||!title.value.trim())throw Error();if(file.value.size>104857600){error.value='Максимальный размер — 100 МиБ';return}await axios.get('/api/v1/auth/me',{timeout:10000});await axios.post(base+'/creatives/upload',file.value,{params:{title:title.value.trim()},headers:{...headers(),'Content-Type':file.value.type||(/\.webm$/i.test(file.value.name)?'video/webm':'video/mp4')},timeout:240000});file.value=null;title.value='';if(fileInput.value)fileInput.value.value='';await load();notice.value='Ролик обработан и сохранён на паузе'})}
function saveCreative(c:any){void action(async()=>{await axios.put(base+'/creatives/'+c.id,{title:c.title,cta_url:c.cta_url,cta_text:c.cta_text,skip_after:c.skip_after==null?null:Number(c.skip_after),status:c.status},{headers:headers()});await load();notice.value='Настройки ролика сохранены'})}
function showPreview(c:any){void action(async()=>{preview.value='';previewId.value=c.id;previewTitle.value=c.title;previewError.value='';preview.value=nodeMediaUrl((await axios.get(base+'/creatives/'+c.id+'/preview',{headers:headers()})).data.media_url)})}
async function catalog(){const r=await axios.get(base+'/videos',{params:{kind:kind.value,q:q.value,offset:offset.value,genre_id:catalogGenre.value??undefined},headers:headers()});videos.value=r.data.items;total.value=r.data.total}
function search(){offset.value=0;void action(catalog)}
function page(n:number){offset.value+=n;void action(catalog)}
function format(s:number){return [Math.floor(s/3600),Math.floor(s%3600/60),Math.floor(s%60)].map(x=>x.toString().padStart(2,'0')).join(':')}
function parse(v:string){if(!/^\d{2}:\d{2}:\d{2}$/.test(v))throw Error('Время: ЧЧ:ММ:СС');const [h,m,s]=v.split(':').map(Number);if(m>59||s>59||h>6)throw Error('Некорректное время');return h*3600+m*60+s}
async function loadTimeline(){const r=(await axios.get(base+'/videos/'+selected.value.kind+'/'+selected.value.id,{headers:headers()})).data;cues.value=r.cues;revision.value=r.revision;source.value=r.source}
function openVideo(v:any){void action(async()=>{await stopPreview();tab.value='timeline';selected.value=v;duration.value=v.duration_sec||0;position.value=0;await loadTimeline()})}
function startPreview(){void action(async()=>{if(!selected.value)return;await stopPreview();const path=selected.value.kind==='movie'?'/api/v1/playback/start':'/api/v1/series_playback/start';const body=selected.value.kind==='movie'?{movie_id:selected.value.id}:{episode_id:selected.value.id};const r=await axios.post(path,body,{headers:headers()});mainUrl.value=nodeMediaUrl(r.data.media_url);if(r.data.session_id){previewSession=r.data.session_id;previewBeat=setInterval(()=>{if(previewSession)void axios.post('/api/v1/playback/heartbeat',{session_id:previewSession},{headers:headers(),timeout:5000}).catch(()=>{})},Math.max(5,r.data.heartbeat_interval_seconds||15)*1000)}})}
function addCue(){try{const seconds=cueKind.value==='mid'?parse(timeInput.value):0;if(cueKind.value==='mid'&&seconds<=0)throw Error('Mid-roll должен быть позже начала');if(cues.value.some(c=>c.kind===cueKind.value&&c.at_sec===seconds))throw Error('Такая точка уже есть');cues.value.push({id:uuid(),kind:cueKind.value,at_sec:seconds,creative_id:creativeId.value||null});error.value=''}catch(e:any){error.value=e.message}}
function seek(e:Event){position.value=Number((e.target as HTMLInputElement).value);timeInput.value=format(position.value);if(main.value)main.value.currentTime=position.value}
function move(c:any,e:Event){try{c.at_sec=parse((e.target as HTMLInputElement).value);error.value=''}catch(e:any){error.value=e.message}}
function saveTimeline(){void action(async()=>{const r=await axios.put(base+'/videos/'+selected.value.kind+'/'+selected.value.id,{revision:revision.value,cues:cues.value},{headers:headers()});revision.value=r.data.revision;source.value='individual';notice.value='Индивидуальные тайминги сохранены';await catalog();await load()})}
function inherit(){if(!confirm('Удалить индивидуальные настройки и применять глобальное правило?'))return;void action(async()=>{await axios.delete(base+'/videos/'+selected.value.kind+'/'+selected.value.id,{headers:headers()});await loadTimeline();await catalog();await load()})}
const ordered=computed(()=>[...cues.value].sort((a,b)=>(a.kind==='pre'?-1:a.kind==='post'?1:0)-(b.kind==='pre'?-1:b.kind==='post'?1:0)||a.at_sec-b.at_sec))
onMounted(()=>void action(async()=>{await load();await catalog();try{genres.value=(await axios.get('/api/v1/genres',{headers:headers()})).data}catch{genres.value=[]}}))

const fileInput=ref<HTMLInputElement|null>(null),previewId=ref(''),previewTitle=ref(''),previewError=ref(''),editing=ref('')
const placements=ref<any[]>([]),selection=ref<any[]>([]),where=ref('videos'),chosen=ref(''),groupGenre=ref<number|null>(null),groupScope=ref('all')
const pre=ref(true),post=ref(false),periodic=ref(false),minutes=ref(20),exact=ref(''),review=ref<any>(null),deleteCandidate=ref<any>(null),deleteUsage=ref<any>(null)
const draft=computed(()=>({creative_id:chosen.value,where:where.value,targets:selection.value,genre_id:groupGenre.value,scope:groupScope.value,preroll:pre.value,postroll:post.value,minutes:periodic.value?minutes.value:0,exact:exact.value}))
watch(draft,()=>{review.value=null},{deep:true,flush:'sync'})
function choose(c:any){chosen.value=c.id;tab.value='setup';review.value=null;notice.value=''}
function toggleSelection(v:any){const i=selection.value.findIndex(x=>x.id===v.id&&x.kind===v.kind);if(i>=0)selection.value.splice(i,1);else selection.value.push(v)}
function selectedVideo(v:any){return selection.value.some(x=>x.id===v.id&&x.kind===v.kind)}
function checkPlacement(){void action(async()=>{review.value=null;const body=placementBody(draft.value);review.value=(await axios.post(base+'/placements/preview',body,{headers:headers()})).data})}
function applyPlacement(){void action(async()=>{if(!review.value)throw Error('Сначала проверьте размещение');const token=review.value.confirmation_token;await axios.post(base+'/placements/apply',{confirmation_token:token},{headers:headers()});review.value=null;await load();await catalog();notice.value='Размещение сохранено. Ролик на паузе не показывается: запустите его в разделе «Ролики», когда будете готовы.'})}
function statusCreative(c:any){if(!confirm(c.status==='active'?'Приостановить все показы этого ролика?':'Запустить ролик? Он начнёт показываться в сохранённых размещениях и активной ротации.'))return;saveCreative({...c,status:c.status==='active'?'paused':'active'})}
function askDelete(c:any){void action(async()=>{deleteUsage.value=(await axios.get(base+'/creatives/'+c.id+'/usage',{headers:headers()})).data;deleteCandidate.value=c})}
function deleteCreative(){void action(async()=>{if(!deleteCandidate.value)return;const id=deleteCandidate.value.id;await axios.delete(base+'/creatives/'+id,{params:{confirm:true},headers:headers()});deleteCandidate.value=null;if(previewId.value===id){preview.value='';previewId.value=''}if(chosen.value===id)chosen.value='';await load();await catalog();notice.value='Ролик удалён из библиотеки и размещений. Статистика сохранена.'})}
function creativeName(id:string|null){return id?creatives.value.find(c=>c.id===id)?.title||'Удалённый ролик':'Ротация активных роликов'}
function groupName(r:any){const scope=r.scope==='movie'?'Все фильмы':r.scope==='episode'?'Все серии':'Весь каталог';return r.genre_id==null?scope:scope+' · '+(genres.value.find(g=>g.id===r.genre_id)?.name||'Жанр '+r.genre_id)}
function timing(r:any){return [r.preroll?'В начале':'',r.interval_sec?'Каждые '+r.interval_sec/60+' мин':'',r.postroll?'В конце':''].filter(Boolean).join(' · ')}
function editGroup(r:any){if(!r.creative_id){error.value='Это правило с ротацией. Для смены ролика создайте размещение для той же группы.';return}chosen.value=r.creative_id;where.value=r.genre_id==null?r.scope:'genre';groupScope.value=r.scope;groupGenre.value=r.genre_id;pre.value=r.preroll;post.value=r.postroll;periodic.value=!!r.interval_sec;minutes.value=r.interval_sec/60||20;exact.value='';tab.value='setup'}
function toggleRule(r:any){if(!confirm(r.enabled?'Приостановить правило? Для этих видео могут начать действовать другие правила.':'Включить правило для доступных видео?'))return;void action(async()=>{const {id,...body}=r;await axios.put(base+'/rules/'+id,{...body,enabled:!r.enabled},{headers:headers()});await load()})}
function removeRule(id:string){if(!confirm('Удалить правило размещения? Индивидуальные настройки сохранятся; для остальных видео могут действовать другие правила.'))return;void action(async()=>{await axios.delete(base+'/rules/'+id,{headers:headers()});await load()})}
</script>
<template>
<section class="studio">
<header><div class="eyebrow">PRIVATE CONTROL PLANE</div><h1>Видео и Реклама <span>Ad Studio</span></h1><p>Загрузите ролик → выберите, где и когда показывать → проверьте и сохраните.</p></header>
<nav aria-label="Управление рекламой"><button :class="{active:tab==='creatives'}" @click="tab='creatives'">Ролики</button><button :class="{active:tab==='setup'}" @click="tab='setup'">Настроить показ</button><button :class="{active:tab==='placements'}" @click="tab='placements'">Все размещения</button><button :class="{active:tab==='timeline'}" @click="tab='timeline'">Точные тайминги видео</button></nav>
<p v-if="error" role="alert" class="error">{{error}}</p><p v-if="notice" role="status" class="notice">{{notice}}</p>
<div v-if="tab==='creatives'">
<form class="panel upload" @submit.prevent="upload"><h2>Загрузить ролик</h2><label>Название<input v-model="title" maxlength="160" required placeholder="Например, летняя акция"></label><label>MP4 / WebM · до 100 МиБ · 0,5–300 секунд<input ref="fileInput" type="file" accept="video/mp4,video/webm" required @change="selectFile"></label><button class="primary" :disabled="busy||!file">Загрузить</button><small>После загрузки ролик на паузе. Ничего не запускается автоматически.</small></form>
<div v-for="c in creatives" :key="c.id" class="panel creative"><div class="row spread"><div><h2>{{c.title}}</h2><span :class="['badge',c.status==='active'?'live':'']">{{c.status==='active'?'Показы включены':'На паузе'}}</span> <small>{{Number(c.duration_sec).toFixed(1)}} сек · {{(c.byte_size/1048576).toFixed(1)}} МиБ</small></div><div class="row"><button :disabled="busy" @click="showPreview(c)">Предпросмотр</button><button class="primary" :disabled="busy" @click="choose(c)">Настроить показ</button><button :disabled="busy" @click="statusCreative(c)">{{c.status==='active'?'Пауза':'Запустить'}}</button></div></div>
<div v-if="previewId===c.id" class="preview-wrap"><p>{{previewTitle}} · предпросмотр через Media Node</p><video v-if="preview" :src="preview" controls playsinline preload="metadata" class="preview" @error="previewError='Не удалось загрузить видео. Обновите ссылку предпросмотра.'"></video><p v-if="previewError" role="alert" class="error">{{previewError}}</p><button :disabled="busy" @click="showPreview(c)">Обновить предпросмотр</button><button @click="preview='';previewId=''">Закрыть</button></div>
<div class="row stats"><span>Показы <b>{{c.impressions}}</b></span><span>Досмотры <b>{{c.completions}}</b></span><span>Переходы <b>{{c.clicks}}</b></span><button @click="editing=editing===c.id?'':c.id">{{editing===c.id?'Скрыть настройки':'Изменить ролик'}}</button><button class="danger" :disabled="busy" @click="askDelete(c)">Удалить из библиотеки</button></div>
<form v-if="editing===c.id" class="grid" @submit.prevent="saveCreative(c)"><label>Название<input v-model="c.title" required maxlength="160"></label><label>Ссылка рекламодателя (необязательно)<input v-model="c.cta_url" type="url" placeholder="https://..."></label><label>Текст кнопки перехода<input v-model="c.cta_text" maxlength="80" placeholder="Пусто — не показывать кнопку"></label><label>Когда можно пропустить<select :value="c.skip_after==null?'no':'yes'" @change="c.skip_after=($event.target as HTMLSelectElement).value==='no'?null:Math.min(5,Math.max(1,Math.floor(c.duration_sec)-1))"><option value="no">Без пропуска</option><option value="yes">Через заданное время</option></select><input v-if="c.skip_after!=null" v-model.number="c.skip_after" type="number" min="1" :max="Math.ceil(c.duration_sec)-1" aria-label="Через сколько секунд разрешить пропуск"></label><button :disabled="busy">Сохранить настройки</button></form></div>
<div v-if="!creatives.length" class="panel empty">Загрузите первый рекламный ролик. Затем нажмите «Настроить показ».</div></div>
<div v-if="tab==='setup'" class="setup">
<div class="panel"><h2>1. Какой ролик показывать?</h2><label>Ролик<select v-model="chosen"><option value="" disabled>Выберите ролик</option><option v-for="c in creatives" :key="c.id" :value="c.id">{{c.title}} · {{c.status==='active'?'Показы включены':'На паузе'}}</option></select></label></div>
<div class="panel"><h2>2. Где показывать?</h2><label>Видео или группа<select v-model="where"><option value="videos">Выбранные видео</option><option value="genre">По жанру</option><option value="movie">Все фильмы</option><option value="episode">Все серии сериалов</option><option value="all">Весь доступный каталог</option></select></label>
<div v-if="where==='genre'" class="grid"><label>Жанр<select v-model="groupGenre"><option :value="null" disabled>Выберите жанр</option><option v-for="g in genres" :key="g.id" :value="g.id">{{g.name}}</option></select></label><label>Что включить<select v-model="groupScope"><option value="all">Фильмы и серии</option><option value="movie">Только фильмы</option><option value="episode">Только серии</option></select></label></div>
<div v-if="where==='videos'"><form class="row filters" @submit.prevent="search"><select v-model="kind" aria-label="Тип видео" @change="search"><option value="movie">Фильмы</option><option value="episode">Серии сериалов</option></select><input v-model="q" maxlength="120" placeholder="Найти видео"><button :disabled="busy">Найти</button></form><div class="video-list"><label v-for="v in videos" :key="v.id" class="check"><input type="checkbox" :checked="selectedVideo(v)" @change="toggleSelection(v)"><span>{{v.title}}<small>{{v.override?'Есть индивидуальные настройки':'Правила группы'}}</small></span></label></div><div class="row"><button :disabled="busy||offset===0" @click="page(-30)">Назад</button><span>{{offset+1}}–{{Math.min(offset+30,total)}} из {{total}}</span><button :disabled="busy||offset+30>=total" @click="page(30)">Далее</button></div><p>Выбрано: {{selection.length}} <button v-if="selection.length" @click="selection=[]">Снять выбор</button></p><div class="row"><button v-for="v in selection" :key="v.kind+v.id" @click="toggleSelection(v)">{{v.title}} ×</button></div></div>
<p>Только доступные фильмы и серии с рабочим источником. Для группы правило действует и на видео, которые появятся в ней позднее.</p></div>
<div class="panel"><h2>3. Когда показывать?</h2><div class="row"><label class="check"><input v-model="pre" type="checkbox">В начале · Pre-roll</label><label class="check"><input v-model="post" type="checkbox">В конце · Post-roll</label><label class="check"><input v-model="periodic" type="checkbox">Во время просмотра · Mid-roll</label></div><label v-if="periodic" class="interval">Каждые N минут<input v-model.number="minutes" type="number" min="1" max="120" step="1"></label><label v-if="where==='videos'">Точные моменты (необязательно, через запятую)<input v-model="exact" placeholder="00:14:20, 00:35:00"></label><p>Индивидуальные настройки важнее правил жанра; правила жанра важнее общего правила. У пользователей с правом «Без рекламы» показов не будет.</p></div>
<div class="panel"><h2>4. Проверить и сохранить</h2><button class="primary" :disabled="busy||!chosen" @click="checkPlacement">Проверить размещение</button><div v-if="review" class="review"><h3>Будет затронуто видео: {{review.affected_count}}</h3><p>Доступно в выборе: {{review.available_count}}. Индивидуальные исключения: {{review.individual_overrides}}.</p><p v-if="review.replaces_existing" class="warning">Существующие настройки выбранных видео или этой группы будут заменены.</p><p v-if="review.creative_paused" class="warning">Ролик на паузе. Размещение сохранится, но показы начнутся только после нажатия «Запустить» в библиотеке.</p><button class="primary" :disabled="busy||review.affected_count===0" @click="applyPlacement">Сохранить размещение</button></div></div></div>
<div v-if="tab==='placements'"><h2>Группы видео</h2><p>Индивидуальные настройки имеют приоритет. При паузе или удалении правила могут применяться другие правила.</p><article v-for="r in rules" :key="r.id" class="panel"><div class="row spread"><div><h2>{{groupName(r)}}</h2><p>{{creativeName(r.creative_id)}} · {{timing(r)}} · {{r.enabled?'Правило включено':'На паузе'}}</p></div><div class="row"><button :disabled="busy" @click="editGroup(r)">Изменить</button><button :disabled="busy||!!r.creative_id&&!creatives.some(c=>c.id===r.creative_id)" @click="toggleRule(r)">{{r.enabled?'Пауза':'Включить'}}</button><button class="danger" :disabled="busy" @click="removeRule(r.id)">Удалить правило</button></div></div></article><p v-if="!rules.length">Групповых размещений пока нет.</p><h2>Отдельные видео</h2><article v-for="v in placements" :key="v.kind+v.id" class="panel"><div class="row spread"><div><h2>{{v.title}}</h2><p v-if="!v.cues.length">Реклама отключена для этого видео</p><p v-for="c in v.cues" :key="c.id">{{c.kind==='pre'?'В начале':c.kind==='post'?'В конце':format(c.at_sec)}} · {{creativeName(c.creative_id)}}</p></div><button :disabled="busy" @click="openVideo(v)">Изменить точки</button></div></article><p v-if="!placements.length">Индивидуальных размещений пока нет.</p></div>
<div v-if="tab==='timeline'"><form class="row panel" @submit.prevent="search"><select v-model="kind" @change="search"><option value="movie">Фильмы</option><option value="episode">Серии сериалов</option></select><select v-model="catalogGenre" @change="search"><option :value="null">Все категории</option><option v-for="g in genres" :key="g.id" :value="g.id">{{g.name}}</option></select><input v-model="q" placeholder="Быстрый поиск" maxlength="120"><button :disabled="busy">Найти</button><span>Доступно: {{total}}</span></form><div class="editor"><aside class="panel catalog"><button v-for="v in videos" :key="v.id" :class="{active:selected?.id===v.id}" @click="openVideo(v)"><strong>{{v.title}}</strong><small>{{v.cue_count+' точек · '+(v.override?'индивидуально':'глобально')}}</small></button><div class="row"><button :disabled="busy||offset===0" @click="page(-30)">Назад</button><button :disabled="busy||offset+30>=total" @click="page(30)">Далее</button></div></aside><div v-if="selected" class="panel timeline"><h2>{{selected.title}}</h2><p>Индивидуальные настройки этого видео заменяют все правила группы. Удалите точку кнопкой «Удалить» и сохраните тайминги.</p><p>Источник: {{source==='individual'?'индивидуальные настройки':source==='global'?'глобальное правило':'не настроено'}}</p><button :disabled="busy" @click="startPreview">Загрузить предпросмотр видео</button><video v-if="mainUrl" ref="main" class="preview" :src="mainUrl" controls @loadedmetadata="duration=main?.duration||duration" @timeupdate="position=main?.currentTime||0;timeInput=format(position)"></video><label>Шкала времени · {{format(position)}}<input type="range" min="0" :max="duration||21600" step="1" :value="position" @input="seek"></label><div class="markers"><button v-for="c in ordered" :key="c.id" :style="{left:(c.kind==='pre'?0:c.kind==='post'?100:100*c.at_sec/(duration||21600))+'%'}" :title="c.kind+' '+format(c.at_sec)" @click="position=c.at_sec;timeInput=format(c.at_sec)">◆</button></div><div class="row"><select v-model="cueKind"><option value="pre">Pre-roll · начало</option><option value="mid">Mid-roll</option><option value="post">Post-roll · конец</option></select><input v-if="cueKind==='mid'" v-model="timeInput" aria-label="Точное время" placeholder="ЧЧ:ММ:СС"><select v-model="creativeId"><option value="">Ротация активных роликов</option><option v-for="c in creatives" :key="c.id" :value="c.id">{{c.title}} · {{c.status}}</option></select><button @click="addCue">Добавить точку</button></div><div v-for="c in ordered" :key="c.id" class="row cue"><b>{{c.kind}}</b><input v-if="c.kind==='mid'" :value="format(c.at_sec)" aria-label="Переместить точку" @change="move(c,$event)"><span v-else>{{c.kind==='pre'?'Начало':'Конец'}}</span><select v-model="c.creative_id"><option :value="null">Ротация активных</option><option v-for="ad in creatives" :key="ad.id" :value="ad.id">{{ad.title}}</option></select><button @click="cues=cues.filter(x=>x.id!==c.id)">Удалить</button></div><p>Пустой индивидуальный список отключает рекламу в этом видео.</p><div class="row"><button :disabled="busy" @click="saveTimeline">Сохранить тайминги</button><button :disabled="busy" @click="inherit">Наследовать глобальное правило</button></div></div><div v-else class="panel empty">Выберите фильм или серию для настройки таймингов.</div></div></div>
<div v-if="deleteCandidate" class="modal-backdrop"><section role="dialog" aria-modal="true" aria-labelledby="delete-title" class="panel dialog"><h2 id="delete-title">Удалить «{{deleteCandidate.title}}» из библиотеки?</h2><p>Ролик исчезнет из библиотеки и ротации. Его точки будут удалены из {{deleteUsage.videos}} видео; групповых правил будет остановлено: {{deleteUsage.group_rules}}.</p><p>Статистика сохраняется. Это не очистка файла из медиахранилища. Отменить удаление в интерфейсе нельзя.</p><div class="row"><button :disabled="busy" @click="deleteCandidate=null">Отмена</button><button class="danger" :disabled="busy" @click="deleteCreative">Удалить из библиотеки</button></div></section></div>
</section></template>
